+  const email = String(formData.get("email") || "").trim();
+
+  if (!email) {
+    formMessage.textContent = "Enter an email address to join.";
+    return;
+  }
+
+  formMessage.textContent = "You're on the list. Watch your inbox for member access.";
+  signupForm.reset();
+});
+

