+const menuToggle = document.querySelector(".menu-toggle");
+const cartButton = document.querySelector(".cart-button");
+const cartCount = document.querySelector(".cart-count");
+const addToCartButtons = document.querySelectorAll(".add-to-cart");
+const countdown = document.querySelector("#countdown");
+const signupForm = document.querySelector(".signup-form");
+const formMessage = document.querySelector(".form-message");
+
+let cartItems = 0;
+let dealSecondsRemaining = 12 * 60 * 60;
+
+menuToggle.addEventListener("click", () => {
+  const isOpen = document.body.classList.toggle("menu-open");
+  menuToggle.setAttribute("aria-expanded", String(isOpen));
+  menuToggle.querySelector(".sr-only").textContent = isOpen ? "Close menu" : "Open menu";
+});
+
+addToCartButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    cartItems += 1;
+    cartCount.textContent = String(cartItems);
+    cartButton.setAttribute("aria-label", `Shopping cart with ${cartItems} ${cartItems === 1 ? "item" : "items"}`);
+
+    button.classList.add("added");
+    button.textContent = "Added";
+
+    window.setTimeout(() => {
+      button.classList.remove("added");
+      button.textContent = "Add to cart";
+    }, 1400);
+  });
+});
+
+function updateCountdown() {
+  const hours = String(Math.floor(dealSecondsRemaining / 3600)).padStart(2, "0");
+  const minutes = String(Math.floor((dealSecondsRemaining % 3600) / 60)).padStart(2, "0");
+  const seconds = String(dealSecondsRemaining % 60).padStart(2, "0");
+
+  countdown.textContent = `${hours}:${minutes}:${seconds}`;
+
+  if (dealSecondsRemaining > 0) {
+    dealSecondsRemaining -= 1;
+  }
+}
+
+updateCountdown();
+window.setInterval(updateCountdown, 1000);
+
+signupForm.addEventListener("submit", (event) => {
+  event.preventDefault();
+
+  const formData = new FormData(signupForm);
+  const email = String(formData.get("email") || "").trim();
+
+  if (!email) {
+    formMessage.textContent = "Enter an email address to join.";
+    return;
+  }
+
+  formMessage.textContent = "You're on the list. Watch your inbox for member access.";
+  signupForm.reset();
+});
+

')
